#!/usr/bin/env python3
"""Harness for driving the hashcards drill web UI and dumping the sqlite db."""
import os, re, sys, json, time, shutil, sqlite3, subprocess, urllib.request, urllib.parse, socket

BIN = "/workspace/executable"

def free_port(p):
    s = socket.socket()
    try:
        s.bind(("127.0.0.1", p)); s.close(); return True
    except OSError:
        s.close(); return False

def make_collection(path, n, prefix="C", extra_files=None):
    if os.path.exists(path):
        shutil.rmtree(path)
    os.makedirs(path)
    lines = []
    for i in range(n):
        lines.append("Q: %s%04d question\nA: %s%04d answer\n" % (prefix, i, prefix, i))
    with open(os.path.join(path, "Deck.md"), "w") as f:
        f.write("\n".join(lines))
    if extra_files:
        for name, content in extra_files.items():
            with open(os.path.join(path, name), "w") as f:
                f.write(content)
    return path

def export_cards(path):
    out = subprocess.run([BIN, "export", path], capture_output=True, text=True)
    if out.returncode != 0:
        raise RuntimeError("export failed: %s %s" % (out.returncode, out.stderr))
    return json.loads(out.stdout)

def qtext(card):
    c = card["content"]
    if "basic" in c: return c["basic"]["question"]
    return c["cloze"]["text"]

class Server:
    def __init__(self, path, port=8307, args=()):
        self.path = path; self.port = port
        cmd = [BIN, "drill", "--port", str(port), "--open-browser", "false"] + list(args) + [path]
        self.cmd = cmd
        self.proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        self.base = "http://127.0.0.1:%d/" % port
        # wait for readiness
        for _ in range(200):
            if self.proc.poll() is not None:
                o, e = self.proc.communicate()
                raise RuntimeError("server exited rc=%s\nSTDOUT:%s\nSTDERR:%s" % (self.proc.returncode, o, e))
            try:
                urllib.request.urlopen(self.base, timeout=1).read()
                return
            except Exception:
                time.sleep(0.05)
        raise RuntimeError("server never came up")

    def get(self, p="/"):
        r = urllib.request.urlopen("http://127.0.0.1:%d%s" % (self.port, p), timeout=10)
        return r.getcode(), r.read().decode("utf-8", "replace")

    def post(self, action):
        data = urllib.parse.urlencode({"action": action}).encode()
        req = urllib.request.Request(self.base, data=data, method="POST")
        try:
            r = urllib.request.urlopen(req, timeout=10)
            return r.getcode(), r.read().decode("utf-8", "replace")
        except urllib.error.HTTPError as e:
            return e.code, e.read().decode("utf-8", "replace")

    def stop(self):
        try:
            self.proc.terminate(); self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()
        try:
            o, e = self.proc.communicate(timeout=5)
        except Exception:
            o, e = "", ""
        return o, e

Q_RE = re.compile(r'<div class="question rich-text">(.*?)</div>', re.S)
DECK_RE = re.compile(r'<div class="card-header"><h1>(.*?)</h1>', re.S)
BTN_RE = re.compile(r'<input[^>]*name="action"[^>]*value="([^"]+)"([^>]*)>')
PROG_RE = re.compile(r'progress-fill" style="width: ([^;]*);')

def parse(html):
    q = Q_RE.search(html)
    btns = []
    for m in BTN_RE.finditer(html):
        btns.append((m.group(1), "disabled" in m.group(2)))
    return {
        "deck": (DECK_RE.search(html).group(1) if DECK_RE.search(html) else None),
        "question": (re.sub(r"<[^>]+>", "", q.group(1)).strip() if q else None),
        "buttons": btns,
        "progress": (PROG_RE.search(html).group(1) if PROG_RE.search(html) else None),
        "len": len(html),
    }

def dump_db(path):
    db = os.path.join(path, "hashcards.db")
    c = sqlite3.connect(db)
    c.row_factory = sqlite3.Row
    out = {}
    for t in ("cards", "sessions", "reviews"):
        out[t] = [dict(r) for r in c.execute("select * from %s" % t)]
    c.close()
    return out

def seed_cards(path, rows):
    """rows: list of dicts with card_hash and column overrides."""
    db = os.path.join(path, "hashcards.db")
    c = sqlite3.connect(db)
    for r in rows:
        cols = list(r.keys())
        c.execute("update cards set %s where card_hash=?" % ",".join("%s=?" % k for k in cols if k != "card_hash"),
                  [r[k] for k in cols if k != "card_hash"] + [r["card_hash"]])
    c.commit(); c.close()

